    String hash = hashRequest(OP_ROUTE_PUBLISH, req);
    Optional<RoutePlanResponse> replay = replayIfPresent(OP_ROUTE_PUBLISH, req.requestId(), hash, RoutePlanResponse.class);
    if (replay.isPresent()) return replay.get();
    try {
        return tx.execute(status -> {
            planRepo.acquirePublishLock();
            int currentVersion = graphRepo.findVersion().orElse(0);
            if (req.graphVersion() != currentVersion) {
                throw conflict("GRAPH_VERSION_CONFLICT", "graphVersion=" + req.graphVersion() + " 与当前图版本 " + currentVersion + " 不一致");
            }
            List<GraphSegment> segments = graphRepo.findSegments();
            Set<String> stations = stationsOf(segments);
            if (!stations.contains(req.fromStation())) throw notFoundStation(req.fromStation());
            if (!stations.contains(req.toStation())) throw notFoundStation(req.toStation());
            if (req.fromStation().equals(req.toStation())) throw badRequest("起终站必须不同: " + req.fromStation());
            LocalDate opDate = req.departUtc().atZone(PlanService.OPERATION_ZONE).toLocalDate();
            Instant dayEnd = opDate.plusDays(1).atStartOfDay(PlanService.OPERATION_ZONE).toInstant();
            List<PathFinder.Path> candidates = PathFinder.findPaths(segments, req.fromStation(), req.toStation());
            List<PublishedSlot> published = planRepo.findPublishedSlots(opDate,
                    segments.stream().map(GraphSegment::segmentId).toList(), List.of());
            PathFinder.Path chosen = null;
            List<RouteSegmentView> chosenViews = null;
            for (PathFinder.Path path : candidates) {
                Instant arrive = req.departUtc().plusSeconds(path.totalMinutes() * 60L);
                if (arrive.isAfter(req.latestArrivalUtc()) || arrive.isAfter(dayEnd)) continue;
                List<RouteSegmentView> views = toSegmentViews(path, req.departUtc());
                if (!conflicts(views, published)) { chosen = path; chosenViews = views; break; }
            }
            if (chosen == null) {
                throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "ROUTE_INFEASIBLE",
                        "无可行路径：全部候选路径超时、跨运营日或区段被占用", List.of());
            }
            long now = System.currentTimeMillis();
            String scheduleKey = "RTE-" + UUID.randomUUID();
            long planId = planRepo.insertPlan(scheduleKey, opDate, PlanStatus.PUBLISHED, now);
            List<Occupancy> occupancies = new ArrayList<>();
            for (int i = 0; i < chosenViews.size(); i++) {
                RouteSegmentView v = chosenViews.get(i);
                occupancies.add(new Occupancy(0L, planId, i, req.trainNo(), v.segmentId(), v.startUtc(), v.endUtc()));
            }
            planRepo.insertOccupancies(planId, occupancies);
            Instant arriveUtc = chosenViews.get(chosenViews.size() - 1).endUtc();
            String segmentIdsJson = toJson(chosen.segmentIds());
            planRepo.insertRouteDetail(new RoutePlanDetail(planId, currentVersion, req.trainNo(),
                    req.fromStation(), req.toStation(), req.departUtc(), arriveUtc,
                    chosen.totalMinutes(), segmentIdsJson), now);
            RoutePlanResponse response = new RoutePlanResponse(scheduleKey, opDate, 1,
                    PlanStatus.PUBLISHED.name(), currentVersion, req.trainNo(), req.fromStation(),
                    req.toStation(), req.departUtc(), arriveUtc, chosen.totalMinutes(), chosenViews);
            idemRepo.insert(OP_ROUTE_PUBLISH, req.requestId(), hash, toJson(response), now);
            return response;
        });
    } catch (DuplicateKeyException e) {
        return replayIfPresent(OP_ROUTE_PUBLISH, req.requestId(), hash, RoutePlanResponse.class)
                .orElseThrow(() -> conflict("ROUTE_PUBLISH_CONFLICT", "寻径发布冲突，请重试"));
    }
}
